entries[354366] = { ["name"] = "Veil of Darkness", ["text"] = "Unlimited range\nInstant\nSylvanas Windrunner is by far one of the most talented fighters from Azeroth, and can execute multiple abilities in quick succession, rapidly changing position to suit her combat needs. While under the effects of Windrunner , spells and abilities strike Sylvanas where she cast Windrunner ." }
